<script setup>
import {ref} from 'vue';import {Head,Link,useForm,router} from '@inertiajs/vue3';import axios from 'axios';import Errors from '../Components/Errors.vue';import {message} from '../art';
const props=defineProps({questions:Object,search:String});const term=ref(props.search),editing=ref(null),form=useForm({content:null,active:true}),file=ref(null),preview=ref(null),status=ref(''),busy=ref(false);
function edit(q){editing.value=q.id;form.content=JSON.parse(JSON.stringify(q.current_version.content));form.active=q.active}
function save(){form.patch('/admin/questions/'+editing.value,{preserveScroll:true,onSuccess:()=>editing.value=null})}
async function upload(publish=false){busy.value=true;status.value='';try{const data=new FormData();data.append('bank',file.value);data.append('publish',publish?'1':'0');if(preview.value)data.append('preview_hash',preview.value.sha256);const r=await axios.post('/admin/import',data);if(publish){status.value=r.data.message;preview.value=null;router.reload({only:['questions']})}else preview.value=r.data.preview}catch(e){status.value=message(e)}finally{busy.value=false}}
</script><template><Head title="Question management"/><h1>Question kitchen</h1><p>Changes create new question versions. Previous exam papers and attempts retain their original content.</p><form class="filterbar" @submit.prevent="router.get('/admin/questions',{search:term})"><label>Question ID or topic<input v-model="term"></label><button>Search</button></form>
<section class="panel"><details><summary>Import a question bank</summary><p>Upload SUSHI bank JSON. Preview the validated item count before publishing.</p><input type="file" accept=".json,application/json" @change="file=$event.target.files[0];preview=null"><button :disabled="!file||busy" @click="upload(false)">Preview import</button><p v-if="preview">{{preview.items}} items validated. {{Object.entries(preview.subjects).map(([s,n])=>s+': '+n).join(' · ')}}</p><button v-if="preview" class="primary" :disabled="busy" @click="upload(true)">Publish this import</button><p role="status">{{status}}</p></details></section>
<article v-for="q in questions.data" :key="q.id" class="panel"><div class="row"><div><strong>{{q.id}} · {{q.subject}}</strong><p>{{q.topic}} · Version {{q.current_version.version}} · {{q.active?'Published':'Retired'}}</p></div><button @click="edit(q)">Edit</button></div><p class="pre">{{q.current_version.content.stem}}</p>
<form v-if="editing===q.id" class="inset" @submit.prevent="save"><label>Topic<input v-model="form.content.topic" required></label><label>Difficulty<select v-model="form.content.tier"><option>Easy</option><option>Average</option><option>Difficult</option></select></label><label>Question<textarea v-model="form.content.stem" rows="5" required></textarea></label><label v-for="(option,i) in form.content.options" :key="i">Option {{String.fromCharCode(65+i)}}<textarea v-model="form.content.options[i]" required></textarea></label><label>Correct answer<select v-model="form.content.key"><option>A</option><option>B</option><option>C</option><option>D</option></select></label><label>Rationale<textarea v-model="form.content.rationale" rows="5" required></textarea></label><label v-for="(text,i) in form.content.expl" :key="i">Explanation {{String.fromCharCode(65+i)}}<textarea v-model="form.content.expl[i]"></textarea></label><label>Answer source<textarea v-model="form.content.raw['Answer Source']"></textarea></label><label class="check"><input v-model="form.active" type="checkbox">Available in new draws</label><Errors :errors="form.errors"/><button class="primary" :disabled="form.processing">Save new version</button><button class="plain" type="button" @click="editing=null">Cancel</button></form></article>
<div class="row"><Link v-if="questions.prev_page_url" :href="questions.prev_page_url">Previous</Link><span>Page {{questions.current_page}} of {{questions.last_page}}</span><Link v-if="questions.next_page_url" :href="questions.next_page_url">Next</Link></div></template>
